from functools import wraps

from flask import Flask, g, redirect, request, session, url_for
from werkzeug.security import check_password_hash, generate_password_hash

app = Flask(__name__)
app.config["SECRET_KEY"] = "dev-only-change-me"

# Demo store; production reads password hashes from the database.
USERS = {"ada@example.com": generate_password_hash("correct-horse-battery")}

def login_required(view):
    @wraps(view)
    def wrapped(*args, **kwargs):
        if getattr(g, "user", None) is None:
            return redirect(url_for("login", next=request.path))
        return view(*args, **kwargs)
    return wrapped

@app.before_request
def load_user():
    email = session.get("user_email")
    g.user = {"email": email} if email else None

@app.post("/login")
def login():
    email = request.form.get("email", "")
    password = request.form.get("password", "")
    stored = USERS.get(email)
    if stored is None or not check_password_hash(stored, password):
        return {"error": "invalid credentials"}, 401
    session.clear()  # drop any state from before the login
    session["user_email"] = email
    return {"signed_in": True}

@app.post("/logout")
def logout():
    session.clear()
    return {"signed_in": False}

@app.get("/dashboard")
@login_required
def dashboard():
    return {"user": g.user["email"]}

